                    pass
        # Do it cleanly:
        if payer in participants:
            payer_share_cents = total_cents - base_cents * (n - 1)
        else:
            payer_share_cents = 0
            # participants each owe base_cents; total distributed = base_cents * n,
            # remainder = total_cents - base_cents*n is absorbed by payer.

        for p in participants:
            if p == payer:
                share_cents = payer_share_cents
            else:
                share_cents = base_cents
            self._balances[p] -= share_cents / 100.0

        # If payer not in participants, subtract remainder that payer absorbs.
        if payer not in participants and remainder != 0:
            self._balances[payer] -= remainder / 100.0

        # Round balances to avoid float drift.
        for m in self._balances:
            self._balances[m] = round(self._balances[m], 2)

    def balances(self) -> dict[str, float]:
        return {m: round(v, 2) for m, v in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        # Working in cents.
        debtors = []
        creditors = []
        for m, bal in self._balances.items():
            cents = int(round(bal * 100))
            if cents < 0:
                debtors.append([m, -cents])
            elif cents > 0:
                creditors.append([m, cents])

        # Sort for determinism: largest creditors and debtors first.
        debtors.sort(key=lambda x: (-x[1], x[0]))
        creditors.sort(key=lambda x: (-x[1], x[0]))

        payments = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            d_name, d_amt = debtors[i]
            c_name, c_amt = creditors[j]
            pay = min(d_amt, c_amt)
            if pay >= 100:  # only propose payments >= 1.00
                payments.append((d_name, c_name, pay / 100.0))
                d_amt -= pay
                c_amt -= pay
            else:
                # Write off the smaller side.
                if d_amt <= c_amt:
                    d_amt = 0
                else:
                    c_amt = 0
                # In both cases the min is < 100; skip.
            debtors[i][1] = d_amt
            creditors[j][1] = c_amt
            if d_amt == 0:
                i += 1
            if c_amt == 0:
                j += 1

        # Guarantee at most n-1 payments. The greedy algorithm already produces at most
        # min(#debtors, #creditors) <= n-1 payments when n>=2. However due to write-offs,
        # we might still be within bound. If it ever exceeds, merge/skip smallest.
        if len(payments) > max(len(self.members) - 1, 0):
            # Combine smallest payments into a single one is complex; simpler: truncate is bad.
            # But mathematically greedy with n members results in <= n-1 nonzero transactions
            # since each payment eliminates at least one party's balance.
            # With write-offs, a party can be eliminated without a payment, so count only decreases.
            # So this branch should never trigger, but keep safe:
            payments = payments[:max(len(self.members) - 1, 0)]

        return payments
